mod graph;mod native;
use hec_native_ic::instance::{pick_instance,factor_base};
fn main(){let mut cases=0;for(g,p)in[(2,101),(3,61),(4,31)]{let inst=pick_instance(p,g).unwrap();let m=factor_base(&inst.curve).len()/2;let expected=inst.ell/3+7;for seed in[20260916,20260917]{for lp in[1,2]{let reference=hec_native_ic::large_prime::run(&inst,m,lp,seed,20_000);let candidate=native::run(&inst,m,lp,seed,20_000);assert_eq!(reference.k,Some(expected),"reference_cap_or_failure");assert_eq!(candidate.k,reference.k,"candidate_discrete_log");assert!(candidate.relation_checks>0&&candidate.projected_checks>0);println!("CURVE_CONTROL genus={g} p={p} c={} ell={} small_base={m} max_lp={lp} seed={seed} reference_trials={} candidate_trials={} reference_rows={} candidate_rows={} candidate_decompositions={} candidate_projected_equations={} scalar_verified=true",inst.c,inst.ell,reference.trials,candidate.trials,reference.rows,candidate.rows,candidate.relation_checks,candidate.projected_checks);cases+=1;}}}assert_eq!(cases,12);println!("PASS native_signed_graph_curve_controls=12 genera=2,3,4 same_instance_reference=true planted_target_scalars_only=true timing_claim=false");}
